class SecureHouseholdManager(models.Manager["Household"]):
    """
    Manager for Household model that ensures family-based permission filtering.
    """

    def for_family(self, family: FamilyGroup) -> QuerySet[Any]:
        """
        Get households for a specific family.

        Args:
            family: FamilyGroup instance

        Returns:
            QuerySet of households filtered by family and active status
        """
        return self.get_queryset().filter(family=family, is_active=True)

    def for_user(self, user: User | AnonymousUser) -> QuerySet[Any]:
        """
        Get households accessible to a specific user based on their family memberships.

        Args:
            user: User instance

        Returns:
            QuerySet of households filtered by user's family permissions
        """
        if not user or not user.is_authenticated:
            return self.none()

        # Get user's active family memberships
        from users.models import FamilyMembership

        memberships = FamilyMembership.objects.filter(
            user=user, is_active=True
        ).select_related("family")

        family_ids = memberships.values_list("family_id", flat=True)

        if not family_ids:
            return self.none()

        return self.get_queryset().filter(family_id__in=family_ids, is_active=True)


